std::string SeaPenTemplateOptionToString(SeaPenTemplateOption value) {
  const char *str = SeaPenTemplateOptionToStringHelper(value);
  if (!str) {
    return base::StringPrintf("Unknown SeaPenTemplateOption value: %i", static_cast<int32_t>(value));
  }
  return str;
}

std::ostream& operator<<(std::ostream& os, SeaPenTemplateOption value) {
  return os << SeaPenTemplateOptionToString(value);
}

